#include <stdio.h>
#include <string.h>
/* ex03：透明传输的两种填充法
 * ① 字节填充（PPP 用）：数据里出现 FLAG(0x7E) 或 ESC(0x7D) 时，
 *    前面插一个 ESC，并把该字节异或 0x20。
 * ② 零比特填充（HDLC 用）：发送方每遇到 5 个连续 1 就插一个 0；
 *    接收方每遇到 5 个连续 1 就把后面的 0 删掉。
 * 目的都是：让「帧定界符」不会在数据里意外出现（实现透明传输）。*/
#define FLAG 0x7E
#define ESC  0x7D

static int byte_stuff(const unsigned char *in, int n, unsigned char *out) {
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (in[i] == FLAG || in[i] == ESC) {
            out[m++] = ESC;
            out[m++] = in[i] ^ 0x20;      /* 异或 0x20 转义 */
        } else {
            out[m++] = in[i];
        }
    }
    return m;
}

static int byte_unstuff(const unsigned char *in, int n, unsigned char *out) {
    int m = 0;
    for (int i = 0; i < n; i++) {
        if (in[i] == ESC && i + 1 < n) out[m++] = in[i + 1] ^ 0x20;
        else                          out[m++] = in[i];
    }
    return m;
}

static int bit_stuff(const char *in, char *out) {
    int ones = 0, m = 0;
    for (int i = 0; in[i]; i++) {
        out[m++] = in[i];
        if (in[i] == '1') {
            ones++;
            if (ones == 5) { out[m++] = '0'; ones = 0; }   /* 5 个 1 后插 0 */
        } else {
            ones = 0;
        }
    }
    out[m] = '\0';
    return m;
}

static int bit_unstuff(const char *in, char *out) {
    int ones = 0, m = 0;
    for (int i = 0; in[i]; i++) {
        out[m++] = in[i];
        if (in[i] == '1') {
            ones++;
            if (ones == 5) { ones = 0; i++; }              /* 跳过插入的 0 */
        } else {
            ones = 0;
        }
    }
    out[m] = '\0';
    return m;
}

int main(void) {
    unsigned char raw[] = {'A', FLAG, 'B', ESC, 'C'};
    unsigned char st[32], un[32];
    int n = byte_stuff(raw, 5, st);
    printf("① 字节填充\n原始字节: A 7E B 7D C（%d 字节）\n", 5);
    printf("填充后  : ");
    for (int i = 0; i < n; i++) printf("%02X ", st[i]);
    printf("（%d 字节，含 2 个 7E 会被误认成定界符的位置已转义）\n", n);
    int u = byte_unstuff(st, n, un);
    printf("还原后  : ");
    for (int i = 0; i < u; i++) printf("%c ", un[i]);
    printf("（%d 字节）\n", u);

    const char *bits = "011111101011111110";
    char sb[64], ub[64];
    int sn = bit_stuff(bits, sb);
    printf("\n② 零比特填充\n原始比特: %s（%d bit）\n", bits, (int)strlen(bits));
    printf("填充后  : %s（%d bit，每 5 个连续 1 后插一个 0）\n", sb, sn);
    int ubn = bit_unstuff(sb, ub);
    printf("还原后  : %s（%d bit）%s\n", ub, ubn,
           strcmp(ub, bits) == 0 ? "  ✓ 与原始一致" : "  ✗ 不一致");

    printf("\n结论：两种填充都是为了「透明传输」——\n");
    printf("      让数据里不管出现什么字节/比特模式，都不会被误判成帧边界。\n");
    printf("      PPP 用字节填充（面向字节），HDLC 用零比特填充（面向比特）。\n");
    return 0;
}
